/* 零依赖 CDP 审计：Node 22 自带 WebSocket，直接驱动本机 Chrome */
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const PORT = 9333;
const FILE = 'file:///C:/Users/yu.zhao/AppData/Local/Temp/skill-up-455385476/index.html';

const chrome = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check',
  `--remote-debugging-port=${PORT}`,
  '--user-data-dir=C:/Users/yu.zhao/AppData/Local/Temp/skill-up-455385476/.check/profile2',
  'about:blank',
], { stdio: 'ignore' });

let ws, msgId = 0;
const pending = new Map();
const consoleErrors = [];

function send(method, params = {}) {
  const id = ++msgId;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((res, rej) => pending.set(id, { res, rej }));
}

async function connect() {
  for (let i = 0; i < 60; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
      const page = list.find(t => t.type === 'page');
      if (page) return page.webSocketDebuggerUrl;
    } catch { /* 还没起来 */ }
    await sleep(250);
  }
  throw new Error('Chrome 未就绪');
}

const url = await connect();
ws = new WebSocket(url);
await new Promise(r => ws.addEventListener('open', r, { once: true }));

ws.addEventListener('message', (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) {
    const { res, rej } = pending.get(m.id);
    pending.delete(m.id);
    m.error ? rej(new Error(JSON.stringify(m.error))) : res(m.result);
    return;
  }
  if (m.method === 'Runtime.exceptionThrown') {
    consoleErrors.push('EXCEPTION: ' + (m.params.exceptionDetails?.exception?.description
      || m.params.exceptionDetails?.text));
  }
  if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) {
    consoleErrors.push(m.params.type.toUpperCase() + ': ' +
      m.params.args.map(a => a.value ?? a.description ?? a.type).join(' '));
  }
  if (m.method === 'Log.entryAdded' && ['error', 'warning'].includes(m.params.entry.level)) {
    consoleErrors.push('LOG/' + m.params.entry.level + ': ' + m.params.entry.text);
  }
});

await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');

async function measure(width, theme) {
  await send('Emulation.setDeviceMetricsOverride', {
    width, height: 900, deviceScaleFactor: 1, mobile: width < 500,
  });
  await send('Page.navigate', { url: FILE });
  await sleep(900);
  if (theme) {
    await send('Runtime.evaluate', {
      expression: `document.documentElement.setAttribute('data-theme', ${JSON.stringify(theme)}); 1`,
    });
    await sleep(200);
  }

  const { result } = await send('Runtime.evaluate', {
    returnByValue: true,
    expression: `(() => {
      const vw = document.documentElement.clientWidth;
      const out = {
        vw,
        docScrollW: document.documentElement.scrollWidth,
        bodyScrollW: document.body.scrollWidth,
        overflowing: [],
      };
      for (const el of document.querySelectorAll('body *')) {
        const cs = getComputedStyle(el);
        if (cs.display === 'none' || cs.visibility === 'hidden') continue;
        const r = el.getBoundingClientRect();
        if (r.width === 0 && r.height === 0) continue;
        if (r.right > vw + 1 || r.left < -1) {
          out.overflowing.push({
            sel: el.tagName.toLowerCase() +
                 (el.id ? '#' + el.id : '') +
                 (typeof el.className === 'string' && el.className
                   ? '.' + el.className.trim().split(/\\s+/).slice(0, 3).join('.') : ''),
            left: Math.round(r.left), right: Math.round(r.right), w: Math.round(r.width),
          });
        }
      }
      out.overflowing = out.overflowing.slice(0, 14);
      return out;
    })()`,
  });
  return result.value;
}

async function smallTargets() {
  const { result } = await send('Runtime.evaluate', {
    returnByValue: true,
    expression: `(() => {
      const bad = [];
      for (const el of document.querySelectorAll('a[href], button, input, select, label')) {
        const r = el.getBoundingClientRect();
        const cs = getComputedStyle(el);
        if (cs.display === 'none' || cs.visibility === 'hidden') continue;
        if (r.width === 0 && r.height === 0) continue;
        // sr-only 的 radio / checkbox 本体不算，它的 label 才是目标
        if (cs.position === 'absolute' && r.width <= 1) continue;
        if (r.height < 44 || r.width < 44) {
          bad.push({ sel: el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') +
            (typeof el.className === 'string' && el.className ? '.' + el.className.trim().split(/\\s+/)[0] : ''),
            w: Math.round(r.width), h: Math.round(r.height) });
        }
      }
      return bad;
    })()`,
  });
  return result.value;
}

async function focusOrder() {
  await send('Runtime.evaluate', { expression: `window.scrollTo(0,0); document.body.focus(); 1` });
  const seen = [];
  for (let i = 0; i < 40; i++) {
    await send('Input.dispatchKeyEvent', {
      type: 'rawKeyDown', windowsVirtualKeyCode: 9, key: 'Tab', code: 'Tab',
    });
    await send('Input.dispatchKeyEvent', {
      type: 'keyUp', windowsVirtualKeyCode: 9, key: 'Tab', code: 'Tab',
    });
    await sleep(35);
    const { result } = await send('Runtime.evaluate', {
      returnByValue: true,
      expression: `(() => {
        const a = document.activeElement;
        if (!a || a === document.body) return null;
        const r = a.getBoundingClientRect();
        const cs = getComputedStyle(a);
        return {
          tag: a.tagName.toLowerCase(),
          id: a.id || null,
          text: (a.textContent || a.getAttribute('aria-label') || '').trim().slice(0, 18),
          outline: cs.outlineStyle + ' ' + cs.outlineWidth + ' ' + cs.outlineColor,
          visible: r.width > 0 || r.height > 0,
        };
      })()`,
    });
    if (result.value) seen.push(result.value);
  }
  return seen;
}

console.log('=== 375px 布局 ===');
console.log(JSON.stringify(await measure(375), null, 1));

console.log('\\n=== 1440px 布局 ===');
console.log(JSON.stringify(await measure(1440), null, 1));

console.log('\\n=== 375px 触控目标 < 44px ===');
console.log(JSON.stringify(await smallTargets(), null, 1));

console.log('\\n=== 375px 深色主题溢出 ===');
console.log(JSON.stringify(await measure(375, 'dark'), null, 1));

console.log('\\n=== 375px 深色下触控目标 ===');
console.log(JSON.stringify(await smallTargets(), null, 1));

console.log('\\n=== 375px 键盘 Tab 顺序 ===');
await measure(375);
const order = await focusOrder();
order.forEach((o, i) => console.log(
  String(i + 1).padStart(2) + '. ' + o.tag + (o.id ? '#' + o.id : '') +
  '  "' + o.text + '"  outline=' + o.outline + (o.visible ? '' : '  [不可见!]')));

console.log('\\n=== 控制台错误 / 警告 ===');
console.log(consoleErrors.length ? consoleErrors.join('\\n') : '(无)');

ws.close();
chrome.kill();
process.exit(0);

