  }
});

await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');

const evalJS = async (expression) => {
  const { result, exceptionDetails } = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.text + ' ' + (exceptionDetails.exception?.description || ''));
  return result.value;
};

async function load(width, theme, reducedMotion = false) {
  await send('Emulation.setDeviceMetricsOverride', { width, height: 900, deviceScaleFactor: 1, mobile: width < 500 });
  await send('Emulation.setEmulatedMedia', {
    features: [
      { name: 'prefers-reduced-motion', value: reducedMotion ? 'reduce' : 'no-preference' },
      { name: 'prefers-color-scheme', value: theme === 'dark' ? 'dark' : 'light' },
    ],
  });
  await send('Page.navigate', { url: FILE });
  await sleep(800);
  await evalJS(`document.documentElement.setAttribute('data-theme', ${JSON.stringify(theme)}); 1`);
  await sleep(180);
}

/* ---------- 对比度探针（WCAG 相对亮度） ---------- */
const CONTRAST_PROBE = `(() => {
  function srgb(c){ c/=255; return c <= 0.03928 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4); }
  function lum(r,g,b){ return 0.2126*srgb(r)+0.7152*srgb(g)+0.0722*srgb(b); }
  function parse(s){
    const m = s.match(/rgba?\\(([^)]+)\\)/); if(!m) return null;
    const p = m[1].split(/[,\\s/]+/).filter(Boolean).map(Number);
    return { r:p[0], g:p[1], b:p[2], a: p.length>3 ? p[3] : 1 };
  }
  function over(fg, bg){ // fg 叠在 bg 上
    return { r: fg.r*fg.a + bg.r*(1-fg.a), g: fg.g*fg.a + bg.g*(1-fg.a), b: fg.b*fg.a + bg.b*(1-fg.a), a:1 };
  }
  function effBg(el){
    let cur = el, acc = null;
    while (cur && cur !== document.documentElement) {
      const c = parse(getComputedStyle(cur).backgroundColor);
      if (c && c.a > 0) { acc = acc ? over(acc, c) : c; if (acc.a >= 1 || c.a >= 1) return acc.a>=1?acc:over(acc,{r:255,g:255,b:255,a:1}); }
      cur = cur.parentElement;
    }
    const base = parse(getComputedStyle(document.body).backgroundColor) || {r:255,g:255,b:255,a:1};
    return acc ? over(acc, base) : base;
  }
  function ratio(a,b){
    const l1 = lum(a.r,a.g,a.b), l2 = lum(b.r,b.g,b.b);
    return (Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05);
  }
  const out = [];
  for (const el of document.querySelectorAll('body *')) {
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') continue;
    // 只取直接包含文字的元素
    const own = Array.from(el.childNodes).some(n => n.nodeType === 3 && n.textContent.trim().length > 1);
    if (!own) continue;
    const r = el.getBoundingClientRect();
    if (r.width === 0 || r.height === 0) continue;
    const fg = parse(cs.color); if (!fg || fg.a === 0) continue;
    const bg = effBg(el);
    const fgc = fg.a < 1 ? over(fg, bg) : fg;
    const size = parseFloat(cs.fontSize);
    const bold = parseInt(cs.fontWeight, 10) >= 700;
    const large = size >= 24 || (size >= 18.66 && bold);
    const need = large ? 3 : 4.5;
    const cr = ratio(fgc, bg);
    out.push({
      sel: el.tagName.toLowerCase() + (el.id ? '#'+el.id : '') +
           (typeof el.className==='string' && el.className ? '.'+el.className.trim().split(/\\s+/).slice(0,2).join('.') : ''),
      text: (el.textContent||'').trim().slice(0,14),
      size: Math.round(size*10)/10, bold, need: need,
      ratio: Math.round(cr*100)/100,
      pass: cr >= need - 0.005,
    });
  }
  const fails = out.filter(o => !o.pass);
  return { total: out.length, fails, min: out.reduce((m,o)=>Math.min(m,o.ratio), 99) };
})()`;

/* ---------- 文本在盒子里是否被截断 ---------- */
const CLIP_PROBE = `(() => {
  const bad = [];
  for (const el of document.querySelectorAll('body *')) {
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') continue;
    if (cs.overflow === 'visible') continue;
    if (el.scrollWidth > el.clientWidth + 1 && el.clientWidth > 0) {
      bad.push({ sel: el.tagName.toLowerCase() + (el.id?'#'+el.id:'') +
        (typeof el.className==='string'&&el.className?'.'+el.className.trim().split(/\\s+/)[0]:''),
        scrollW: el.scrollWidth, clientW: el.clientWidth,
        text: (el.textContent||'').trim().slice(0,20) });
    }
  }
  return bad;
})()`;

