    focus: document.activeElement.id || document.activeElement.tagName,
    errors: ['email','frequency','consent'].filter(n => !document.getElementById(n+'-error').hidden)
      .map(n => n + ': ' + document.querySelector('#'+n+'-error [data-error-text]').textContent),
